const WS = constants.WS;
const access = variables.access || {};
const isAdmin = !!(access.is && access.is.admin);
const isBuilder = !!(access.is && access.is.builder);
const hasAllDomains = !!access.has_all_domains;
const accessDomains = (Array.isArray(access.domains) ? access.domains : []).map(s => String(s).toLowerCase());

const URL = window.location.origin + '/api/tooljet-db/proxy/' + constants.UTIL_TABLE + '?tj_app_id=not.is.null&order=name.asc';
const HDRS = { credentials: 'include', headers: { 'Tj-Workspace-Id': WS } };

const safeFetch = async function() {
  try {
    const r = await fetch(URL, HDRS);
    if (!r.ok) { console.warn('[loadDomains] HTTP', r.status); return null; }
    const text = await r.text();
    if (!text) { console.warn('[loadDomains] empty body'); return null; }
    try { return JSON.parse(text); }
    catch (e) { console.warn('[loadDomains] invalid JSON:', String(text).slice(0,120)); return null; }
  } catch (e) { console.warn('[loadDomains] fetch threw:', e && e.message); return null; }
};

let rows = await safeFetch();
if (rows === null) {
  await new Promise(function(res){ setTimeout(res, 600); });
  rows = await safeFetch();
}
if (rows === null) {
  await actions.setVariable('domainValues', []);
  await actions.setVariable('domainLabels', []);
  return [];
}

const allNames = (Array.isArray(rows) ? rows : []).map(function(row){ return row.name; }).filter(Boolean);

let visibleNames;
if (isAdmin || isBuilder || hasAllDomains) {
  visibleNames = allNames;
} else {
  visibleNames = allNames.filter(function(name){
    const key = name.replace(/\s+/g, '_').toLowerCase();
    return accessDomains.includes(key);
  });
}

await actions.setVariable('domainValues', visibleNames);
await actions.setVariable('domainLabels', visibleNames);
return visibleNames;
